"""w03: build writeup/key_numbers.json and check it against writeup/README.md.
Each entry: readme_text (exact text in the README), quantity, value, uncertainty, method, source (paths relative to
tic214/; the first one is the primary source), optional note. Checks: (1) every readme_text occurs in the README;
(2) every numeric token of the README (outside code spans, link targets, image tags, list markers and the phase column)
lies inside the span of at least one entry; (3) every source path exists."""
import json, os, re, sys
W = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))   # the write-up folder (writeup/ or tic214311908/)
B = os.path.dirname(W) if os.path.isdir(os.path.join(os.path.dirname(W), 'clean')) else os.path.join(W, 'analysis')
K = []
def E(text, quantity, value, unc, method, source, note=None):
    d = dict(readme_text=text, quantity=quantity, value=value, uncertainty=unc, method=method,
             source=[s.strip() for s in source.split(';')])
    if note: d['note'] = note
    K.append(d)

