out = dict(description="Every number in writeup/README.md with value, uncertainty, method and source file (paths relative to "
           "the tic214/ analysis root; in the repository they live under analysis/<folder>/, writeup files at the folder top level). "
           "readme_text is the exact text as it appears in the README.", n_entries=len(K), entries=K)
json.dump(out, open(f'{W}/key_numbers.json', 'w'), indent=1, ensure_ascii=False)

T = open(f'{W}/README.md').read()
bad = [k['readme_text'] for k in K if k['readme_text'] not in T]
cov = [False]*len(T)
for k in K:
    i = T.find(k['readme_text'])
    while i >= 0:
        for j in range(i, i + len(k['readme_text'])): cov[j] = True
        i = T.find(k['readme_text'], i + 1)
excl = [False]*len(T)
for pat in (r'`[^`]*`', r'\]\([^)]*\)', r'!\[[^\]]*\]', r'(?m)^\s*\d+\. ', r'(?m)^\| [123] \|'):
    for m in re.finditer(pat, T):
        for j in range(m.start(), m.end()): excl[j] = True
unc = []
for m in re.finditer(r'(?<![A-Za-z_\d.])\d[\d,]*(?:\.\d+)?(?![A-Za-z])', T):
    if excl[m.start()] or cov[m.start()]: continue
    line = T[:m.start()].count('\n') + 1
    unc.append((line, m.group(), T[max(0, m.start()-30):m.end()+20].replace('\n', ' ')))
def _path(s): return os.path.join(W, s[len('writeup/'):]) if s.startswith('writeup/') else os.path.join(B, s)
missing_src = sorted({s for k in K for s in k['source'] if not os.path.exists(_path(s))})
print('entries', len(K))
print('readme_text not found:', bad)
print('uncovered numbers:', len(unc))
for u in unc: print('  ', u)
print('missing sources:', missing_src)
